def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    sys.setrecursionlimit(max(sys.getrecursionlimit(), 1_000_000))

    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/(),:=<>]")
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2}
    values = {}
    active = set()

    def parse(content):
        tokens = token_pattern.findall(content[1:])
        pos = 0

        def expression(min_precedence=0):
            nonlocal pos

            negative = False
            while tokens[pos] == "-":
                negative = not negative
                pos += 1

            token = tokens[pos]
            pos += 1

            if token == "(":
                node = expression()
                pos += 1  # )
            elif token.isdigit():
                node = ("number", int(token))
            elif token in ("SUM", "MIN", "MAX"):
                pos += 1  # (
                args = []
                while True:
                    if pos + 1 < len(tokens) and tokens[pos + 1] == ":":
                        start = tokens[pos]
                        end = tokens[pos + 2]
                        pos += 3
                        args.append(("range", start, end))
                    else:
                        args.append(expression())
                    if tokens[pos] == ")":
                        pos += 1
                        break
                    pos += 1  # ,
                node = ("function", token, args)
            elif token == "IF":
                pos += 1  # (
                left = expression()
                comparison = tokens[pos]
                pos += 1
                right = expression()
                pos += 1  # ,
                then = expression()
                pos += 1  # ,
                otherwise = expression()
                pos += 1  # )
                node = ("if", comparison, left, right, then, otherwise)
            else:
                node = ("cell", token)

            if negative:
                node = ("negate", node)

            while pos < len(tokens):
                op = tokens[pos]
                op_precedence = precedence.get(op, 0)
                if op_precedence <= min_precedence:
                    break
                pos += 1
                right = expression(op_precedence)
                node = ("binary", op, node, right)

            return node

        return expression()

    def function_arguments(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue

            start, end = arg[1], arg[2]
            first_column = min(ord(start[0]), ord(end[0]))
            last_column = max(ord(start[0]), ord(end[0]))
            first_row = min(int(start[1:]), int(end[1:]))
            last_row = max(int(start[1:]), int(end[1:]))

            for row in range(first_row, last_row + 1):
                for column in range(first_column, last_column + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("cell", name)

    def evaluate(name):
        results = []
        tasks = [("cell", name)]

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                cell = task[1]
                if cell in values:
                    results.append(values[cell])
                elif cell not in cells:
                    results.append(0)
                elif cell in active:
                    results.append("#CYCLE!")
                else:
                    active.add(cell)
                    content = cells[cell]
                    tasks.append(("finish_cell", cell))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content)))
                    else:
                        results.append(int(content))

            elif kind == "finish_cell":
                cell = task[1]
                values[cell] = results[-1]
                active.remove(cell)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "cell":
                    tasks.append(("cell", node[1]))
                elif node_kind == "negate":
                    tasks.append(("negate",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                elif node_kind == "if":
                    tasks.append(("if_left", node))
                    tasks.append(("eval", node[2]))
                else:
                    tasks.append(
                        ("function_next", node[1], iter(function_arguments(node[2])), None)
                    )

            elif kind == "negate":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif right == 0:
                    results.append("#DIV/0!")
                else:
                    quotient = abs(left) // abs(right)
                    results.append(-quotient if (left < 0) != (right < 0) else quotient)

            elif kind == "if_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    node = task[1]
                    tasks.append(("if_right", node, left))
                    tasks.append(("eval", node[3]))

            elif kind == "if_right":
                node, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                else:
                    op = node[1]
                    if op == "=":
                        condition = left == right
                    elif op == "<>":
                        condition = left != right
                    elif op == "<":
                        condition = left < right
                    elif op == "<=":
                        condition = left <= right
                    elif op == ">":
                        condition = left > right
                    else:
                        condition = left >= right
                    tasks.append(("eval", node[4] if condition else node[5]))

            elif kind == "function_next":
                function, arguments, accumulated = task[1:]
                argument = next(arguments, None)
                if argument is None:
                    results.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append(("function_value", function, arguments, accumulated))
                    tasks.append(("eval", argument))

            else:  # function_value
                function, arguments, accumulated = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if accumulated is None:
                        accumulated = value
                    elif function == "SUM":
                        accumulated += value
                    elif function == "MIN":
                        accumulated = min(accumulated, value)
                    else:
                        accumulated = max(accumulated, value)
                    tasks.append(("function_next", function, arguments, accumulated))

        return results[-1]

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
